CREATE TABLE IF NOT EXISTS web_service_checklist_photos (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 operation_id uuid NOT NULL REFERENCES web_service_operations(id) ON DELETE CASCADE,
 stage_id text NOT NULL,field_id text NOT NULL,filename text NOT NULL,mime text NOT NULL,
 content bytea NOT NULL CHECK(octet_length(content)<=3145728),
 created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE web_service_checklist_photos ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON web_service_checklist_photos FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS web_service_checklist_photos_operation ON web_service_checklist_photos(operation_id);
-- Add the blank CCP template without replacing customized templates or activating any rule.
